 static final BlockPos Q=new BlockPos(1280,205,8);static int ticks,stage=-1;static long due;static WorkerGolem g,spawned;static GolemDart launched;static SealEntity s,dest;static ChestBlockEntity out;static ItemEntity outsideX,outsideY,outsideZ;static boolean tested;
