 static void area(ServerPlayer p,SealEntity seal,SealArea target){var old=p.position();p.setPos(Vec3.atCenterOf(seal.getBlockPos()));if(!seal.oriented())check(seal.edit(p,17),"Area toggle rejected");for(int a=0;a<3;a++)for(int n=0;n<8;n++){var v=seal.areaConfig();int x=a==0?v.x():a==1?v.y():v.z(),want=a==0?target.x():a==1?target.y():target.z();if(x==want)break;check(seal.edit(p,18+a*2+(x<want?1:0)),"Area control rejected");}p.setPos(old);}
