 if(stage==1){check(now<due,"Oriented pickup timeout "+g.position());if(GolemClient.count(out,Items.EMERALD)!=17)return;check(outsideX.isAlive()&&outsideY.isAlive()&&outsideZ.isAlive()&&GolemClient.count(out,Items.DIAMOND)==0,"Oriented pickup crossed a boundary");g.setMode(2);p.openMenu(s);stage=2;Thaumcraft.LOGGER.info("AREA_PICKUP_OK: seventeen real emeralds collected; X/Y/Z sentinel stacks untouched. Ready for native X+ click.");return;}
 if(stage==2&&s.areaConfig().x()==4){g.setMode(0);stage=3;due=now+500;return;}
 if(stage==3){check(now<due,"Expanded X pickup timeout");if(GolemClient.count(out,Items.DIAMOND)!=13)return;check(!outsideX.isAlive()&&outsideY.isAlive()&&outsideZ.isAlive(),"X control changed Y/Z boundaries");stage=4;Thaumcraft.LOGGER.info("AREA_GUI_X_OK: native X+ admits thirteen diamonds, Y/Z sentinels remain excluded. Ready for Y+.");return;}
 if(stage==4&&s.areaConfig().y()==2){stage=5;due=now+500;return;}
 if(stage==5){check(now<due,"Expanded Y pickup timeout");if(GolemClient.count(out,Items.DIAMOND)!=20)return;check(!outsideY.isAlive()&&outsideZ.isAlive(),"Y control changed Z boundary");stage=6;Thaumcraft.LOGGER.info("AREA_GUI_Y_OK: native Y+ admits seven elevated diamonds; Z sentinel remains excluded. Ready for Z+.");return;}
 if(stage==6&&s.areaConfig().z()==3){stage=7;due=now+500;return;}
 if(stage==7){check(now<due,"Expanded Z pickup timeout");if(GolemClient.count(out,Items.GOLD_INGOT)!=11)return;check(!outsideZ.isAlive()&&g.cargo.isEmpty()&&g.progress().equals(new GolemProgress(0,8)),"Z pickup duplicated cargo or XP");p.closeContainer();clear(l);g.discard();s=GolemProbe.seal(p,SealKind.BREAKER,Q.east(5));l.setBlockAndUpdate(s.getBlockPos(),s.getBlockState().setValue(SealBlock.FACING,Direction.EAST));l.setBlockAndUpdate(s.support(),Blocks.STONE.defaultBlockState());area(p,s,new SealArea(3,1,1));l.setBlockAndUpdate(Q.east(6),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(Q.east(7),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(Q.east(8),Blocks.DIAMOND_BLOCK.defaultBlockState());g=spawn(p,new GolemDesign(1,1,3,0),Q.east(2));stage=8;due=now+500;Thaumcraft.LOGGER.info("AREA_GUI_Z_OK: native Z+ admits eleven gold ingots, exact transfer XP; starting directional breaker.");return;}
 if(stage==8){check(now<due,"Oriented breaker timeout "+g.position());if(!l.isEmptyBlock(Q.east(6))||!l.isEmptyBlock(Q.east(7)))return;check(l.getBlockState(s.support()).is(Blocks.STONE)&&l.getBlockState(Q.east(8)).is(Blocks.DIAMOND_BLOCK)&&g.cargo.isEmpty()&&l.getEntitiesOfClass(ItemEntity.class,new AABB(s.getBlockPos()).inflate(4),item->item.getItem().is(Items.COBBLESTONE)).stream().mapToInt(item->item.getItem().getCount()).sum()==2,"Breaker escaped forward area, broke support or lost physical drops");l.removeBlock(s.support(),false);l.removeBlock(Q.east(8),false);clear(l);g.dropCargo(l);g.discard();s=GolemProbe.seal(p,SealKind.HARVEST,Q);area(p,s,new SealArea(2,1,1));for(var q:List.of(Q.east(),Q.east(2))){l.setBlockAndUpdate(q.below(),Blocks.FARMLAND.defaultBlockState());l.setBlockAndUpdate(q,((CropBlock)Blocks.WHEAT).getStateForAge(7));}g=spawn(p,new GolemDesign(3,1,1,0),Q.west(2));stage=9;due=now+500;Thaumcraft.LOGGER.info("AREA_BREAKER_OK: east-facing breaker cut exactly two forward blocks, support and outer diamond block intact.");return;}
 if(stage==9){check(now<due,"Oriented harvest timeout "+g.position());if(l.getBlockState(Q.east()).getValue(CropBlock.AGE)==7)return;check(l.getBlockState(Q.east(2)).getValue(CropBlock.AGE)==7,"Harvest escaped X area");l.removeBlock(Q.east(),false);l.removeBlock(Q.east(2),false);clear(l);g.dropCargo(l);g.discard();s=GolemProbe.seal(p,SealKind.LUMBER,Q);area(p,s,new SealArea(2,2,1));for(int n=0;n<3;n++)l.setBlockAndUpdate(Q.east().above(n),Blocks.OAK_LOG.defaultBlockState());g=spawn(p,new GolemDesign(1,1,3,0),Q.west(2));stage=10;due=now+500;Thaumcraft.LOGGER.info("AREA_HARVEST_OK: one crop harvested/replanted, outside mature crop untouched.");return;}
 if(stage==10){check(now<due,"Oriented lumber timeout "+g.position());if(l.getBlockState(Q.east()).is(Blocks.OAK_LOG)||l.getBlockState(Q.east().above()).is(Blocks.OAK_LOG))return;check(l.getBlockState(Q.east().above(2)).is(Blocks.OAK_LOG)&&g.cargo.getItem(0).getCount()==2,"Lumber escaped configured height");l.removeBlock(Q.east().above(2),false);clear(l);g.dropCargo(l);g.discard();s=GolemProbe.seal(p,SealKind.GUARD_ADVANCED,Q.east(5));area(p,s,new SealArea(5,2,2));g=spawn(p,new GolemDesign(3,1,4,0),Q.west(3));var victim=BatRiftClient.mob(p,Vec3.atBottomCenterOf(Q.east(9)));check(GolemCombat.eligible(l,p,g,s,victim),"In-area combat target rejected");check(GolemDart.fire(l,g,p,s,victim)&&launched!=null&&launched.mayHit(victim),"In-area dart launch failed");var old=p.position();p.setPos(Vec3.atCenterOf(s.getBlockPos()));check(s.edit(p,18)&&!GolemCombat.eligible(l,p,g,s,victim)&&!launched.mayHit(victim),"Shrunk area retains outside target");p.setPos(old);launched.discard();victim.discard();g.setMode(2);clear(l);s=GolemProbe.seal(p,SealKind.PICKUP_ADVANCED,Q);area(p,s,new SealArea(4,2,3));p.openMenu(s);tested=true;stage=11;Thaumcraft.LOGGER.info("AREA_CLIENT_OK: pickup, native axis controls, directional breaker, bounded harvest/lumber, combat shrink and legacy-safe workflow. Ready for relevant area screenshot.");}
